t.script:
// 
document.addEventListener("DOMContentLoaded", function () {
    var phoneInput = document.querySelector("#phone");
    var hiddenPhone = document.querySelector("#customer_phone");
    var form = phoneInput ? phoneInput.closest("form") : null;

    if (phoneInput) {
        var iti = window.intlTelInput(phoneInput, {
            initialCountry: "bd",
            separateDialCode: true,
            utilsScript: "https://cdnjs.cloudflare.com/ajax/libs/intl-tel-input/17.0.8/js/utils.js"
        });

        if (form && hiddenPhone) {
            form.addEventListener("submit", function (e) {
                phoneInput.setCustomValidity("");


                if (!iti.isValidNumber()) {
                    phoneInput.setCustomValidity("Please enter a valid phone number.");
                    phoneInput.reportValidity(); 
                    phoneInput.focus();
                    e.preventDefault();
                    return false;
                }


                hiddenPhone.value = iti.getNumber();
            });

            phoneInput.addEventListener("input", function() {
                phoneInput.setCustomValidity(""); 
            });
        }
    }


    var courierRadio = document.getElementById("delivery_courier");
    var walkinRadio = document.getElementById("delivery_walk");
    var customerLocationDiv = document.getElementById("customer_location_div");
    var courierServiceDiv = document.getElementById("courier_service_div");
    var courierSelectInput = document.getElementById("courier_service_id");

    function toggleDeliveryFields() {
        if (courierRadio && courierRadio.checked) {
            if (customerLocationDiv) customerLocationDiv.classList.remove("d-none");
            if (courierServiceDiv) courierServiceDiv.classList.remove("d-none");
            if (courierSelectInput) courierSelectInput.setAttribute("required", "required");
        } else {
            if (customerLocationDiv) customerLocationDiv.classList.add("d-none");
            if (courierServiceDiv) courierServiceDiv.classList.add("d-none");
            if (courierSelectInput) {
                courierSelectInput.removeAttribute("required");
                courierSelectInput.value = ""; 
            }
        }
    }

    if (courierRadio) courierRadio.addEventListener("change", toggleDeliveryFields);
    if (walkinRadio) walkinRadio.addEventListener("change", toggleDeliveryFields);

    toggleDeliveryFields();
});
//
